#include <stddef.h>

class item;

extern void* operator new(unsigned int, unsigned int, const char*, int);

class item_vector
{
public:
  item** start;
  item** finish;
  item** end_of_storage;

  void push_back(item* const& value)
  {
    if (finish != end_of_storage)
    {
      if (finish)
        *finish = value;
      ++finish;
    }
    else
      insert_aux(finish, value);
  }

  void insert_aux(item**, item* const&);
};

class world_dynamics_system
{
  char pad[300];
  void* cur_global_so;
public:
  void* get_current_level_global_script_object() const { return cur_global_so; }
};

extern world_dynamics_system* g_world_ptr;

class entity
{
  char pad[280];
  struct container_info
  {
    item_vector items;
  };
  container_info* coninfo;
public:
  bool is_container() const { return coninfo ? true : false; }
  virtual bool add_item(item* it);
  item* find_like_item(item* it) const;
};

class item : public entity
{
public:
  virtual void set_visible(bool);
  virtual void set_count(int);
  virtual int get_number() const;
  virtual bool is_brain_weapon() const;
  void spawn_item_script();
};

